-- Hosbah (MH-576 D5): one row per server a script_runs run targets. operation_id names the
-- operations row the queue actually runs (agentproto script.run); status mirrors the operation's
-- (pending -> sent -> running -> ok/failed/timeout) so a run's per-server tab and history need no
-- join back to operations for the common case. exit_code and the timestamps are filled from the
-- operation's own result once it finishes. output is the tail (1 MiB) of what the script printed,
-- SEALED with the team's DEK and bound to this row's id, the same way a schedule run's output is
-- (internal/schedules/service.go outputContext/SealOutput) — never the operation's own log rows,
-- which are the source but are not kept forever.
ALTER TABLE script_run_servers ADD CONSTRAINT script_run_servers_status_check
  CHECK (status IN ('pending', 'sent', 'running', 'ok', 'failed', 'timeout'));
CREATE INDEX script_run_servers_run_idx ON script_run_servers (team_id, script_run_id);
CREATE INDEX script_run_servers_server_idx ON script_run_servers (team_id, server_id, created_at DESC);
CREATE UNIQUE INDEX script_run_servers_operation_key ON script_run_servers (operation_id) WHERE operation_id IS NOT NULL;
